function calcGradePoint(total) {
  if (total >= 70)
    return { grade: "A", gradePoint: 5, remarks: "Distinction" };
  if (total >= 60) return { grade: "B", gradePoint: 4, remarks: "Credit" };
  if (total >= 50) return { grade: "C", gradePoint: 3, remarks: "Merit" };
  if (total >= 45) return { grade: "D", gradePoint: 2, remarks: "Pass" };
  if (total >= 40)
    return { grade: "E", gradePoint: 1, remarks: "Marginal Pass" };
  return { grade: "F", gradePoint: 0, remarks: "Fail" };
}
function getStudentDepartment(student, departments) {
  return departments.find((d2) => String(d2.id) === String(student.departmentId));
}
function getStudentFaculty(student, departments, faculties) {
  const dept = getStudentDepartment(student, departments);
  if (!dept) return void 0;
  return faculties.find((f2) => String(f2.id) === String(dept.facultyId));
}
function getAcademicStanding(gpa) {
  if (gpa >= 2)
    return {
      label: "Good Standing",
      color: "text-success",
      badgeClass: "bg-success/10 text-success border border-success/20"
    };
  if (gpa >= 1)
    return {
      label: "Probation",
      color: "text-warning",
      badgeClass: "bg-warning/10 text-warning border border-warning/20"
    };
  return {
    label: "Withdrawal Risk",
    color: "text-destructive",
    badgeClass: "bg-destructive/10 text-destructive border border-destructive/20"
  };
}
function makeResult(id2, studentId, courseId, ca, exam, status) {
  const total = ca + exam;
  const { grade, gradePoint, remarks } = calcGradePoint(total);
  return {
    id: id2,
    studentId,
    courseId,
    caScore: ca,
    examScore: exam,
    totalScore: total,
    grade,
    gradePoint,
    remarks,
    status
  };
}
